cell=S.plate.find(c=>c.id===S.selectedCellId);if(!cell){toast('Select a cell first.');break}cell.stained=true;cell.stainIntensity=clamp(cell.viability*.7+cell.membrane*.3,0,100);S.events.unshift({tick:S.tick,type:'lab',text:`Fluorescent viability stain applied to ${cell.id}.`});addNotebook('Fluorescent stain applied',`${cell.id} stained; fluorescence intensity proxy ${f(cell.stainIntensity,1)}% combines viability and membrane integrity.`,'STAINING');storeState();render();toast('Selected cell stained; fluorescence reflects viability and membrane integrity.');break}case'remove-cell':{if(S.plate.length<=1){toast('Keep at least one cell on the observatory plate.');break}let index=S.plate.findIndex(c=>c.id===S.selectedCellId);if(index<0)break;let [removed]=S.plate.splice(index,1);S.selectedCellId=S.plate[Math.min(index,S.plate.length-1)].id;storeState();render();toast(`${removed.id} removed from the plate.`);break}case'add-note':$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h2>Add field note</h2><button class="modal-close" data-action="close-modal">×</button></div><label>Observation title</label><input id="note-title" placeholder="e.g. Increased stress response" maxlength="90"><label>Notes / hypothesis</label><textarea id="note-body" placeholder="Record an observation, hypothesis, or next step…"></textarea><div class="modal-footer"><button class="subtle-button" data-action="close-modal">Cancel</button><button class="action-button primary" data-action="save-note">Save to notebook</button></div></div></div>`;break;case'save-note':{let title=$('#note-title')?.value.trim(),text=$('#note-body')?.value.trim();if(!title||!text){toast('Add a title and observation first.');return}addNotebook(title,text);$('#modal-root').innerHTML='';currentView='notebook';render();toast('Field note saved.');break}case'export':download('genesis-database.json',JSON.stringify({format:'genesis-genome-archive-v1',archive:S.archive||[],partArchive:S