document.addEventListener('click',e=>{let nav=e.target.closest('[data-view]');if(nav){currentView=nav.dataset.view;render();return}let plateCell=e.target.closest('[data-plate-cell]');if(plateCell){S.selectedCellId=plateCell.dataset.plateCell;storeState();render();return}let element=e.target.closest('[data-element]');if(element){S.selectedElement=element.dataset.element;storeState();render();return}let action=e.target.closest('[data-action]');if(action){handleAction(action);return}let p=e.target.closest('[data-protocol]');if(p){activeProtocol=p.dataset.protocol;render();return}let sp=e.target.closest('[data-speed]');if(sp){S.speed=Number(sp.dataset.speed);storeState();render();return}let gene=e.target.closest('[data-gene]');if(gene){S.selectedGene=Number(gene.dataset.gene);render();return}if(e.target.closest('#new-world')){newWorld();return}if(e.target.closest('#settings-btn')){$('#modal-root').innerHTML=settingsModal();return}if(e.target.closest('#seed-button')){navigator.clipboard?.writeText(String(S.seed));toast('World seed copied.');return}if(e.target.classList.contains('modal-backdrop'))$('#modal-root').innerHTML=''});
document.addEventListener('input',e=>{if(e.target.matches('[data-env]')){let key=e.target.dataset.env;S.env[key]=Number(e.target.value);let label=e.target.closest('.env-control')?.querySelector('label b');if(label){let unit=label.textContent.replace(/^[-+\d.,\s]+/,'');label.textContent=`${f(S.env[key],1)} ${unit}`.trim()}} });
document.addEventListener('change',e=>{if(e.target.matches('[data-env]')){storeState();render()}if(e.target.id==='setting-speed'){S.speed=Number(e.target.value);storeState()}if(e.target.id==='import-file'&&e.target.files?.[0]){let reader=new FileReader();reader.onload=()=>{try{let data=JSON.parse(reader.result),genomes=Array.isArray(data.archive)?data.archive:data.genome?[data.genome]:data.genes&&data.sequence?[data]:[],parts=Array.isArray(data.partArchive)?data.partArchive:[];if(!Array.isArray(genomes)||!Array.isArray(parts)||(!genomes.length&&!parts.length))throw Error('No genome or cellular-part archive records found');if(genomes.some(g=>!g?.genes||!g?.sequence))throw Error('An imported genome is missing its sequence or gene annotations');if(parts.some(part=>!partDefinition(part?.typeId)||!part.sourceCell||!Number.isFinite(Number(part.quality))))throw Error('An imported cellular-part record is incomplete or unsupported');S.archive=S.archive||[];let genomeIds=new Set(S.archive.map(g=>g.id));genomes.forEach(g=>{if(!genomeIds.has(g.id)){S.archive.unshift({...g,saved:g.saved||new Date().toLocaleDateString()});genomeIds.add(g.id)}});S.partArchive=S.partArchive||[];let partIds=new Set(S.partArchive.map(part=>part.id));parts.forEach(part=>{if(!partIds.has(part.id)){S.partArchive.push({...part,quality:clamp(Number(part.quality),0,1)});partIds.add(part.id)}});S.partSequence=Math.max(S.partSequence||0,Number(data.partSequence)||0,...S.partArchive.map(part=>Number(String(part.id||'').match(/(\\d+)$/)?.[1])||0));if(Array.isArray(data.notebook)){S.notebook=S.notebook||[];let noteIds=new Set(S.notebook.map(note=>note.id));data.notebook.forEach(note=>{if(note?.id&&!noteIds.has(note.id)){S.notebook.push(note);noteIds.add(note.id)}})}storeState();render();toast(`Imported ${genomes.length} genome${genomes.length===1?'':'s'} and ${parts.length} cellular-part proxy record${parts.length===1?'':'s'}.`)}catch(err){toast(`Import failed: ${err.message}`)}finally{e.target.value=''}};reader.readAsText(e.target.files[0])}});
window.addEventListener('resize',()=>{if(currentView==='overview'){drawEcosystem();drawTrend()}});render();
