 function genomeView(){let genome=S.inspectedGenome||S.genome,g=genome.genes[S.selectedGene]||genome.genes[0],slice=g.promoter+g.enhancer+g.coding.slice(0,18)+g.intron.slice(0,16)+g.coding.slice(18),sequence=slice.split('').map((x,i)=>`<span class="${i<g.promoter.length?'promoter':i>=g.promoter.length+g.enhancer.length&&i<g.promoter.length+g.enhancer.length+g.coding.length?'highlight':''}">${x}</span>`).join('');let lineageCells=S.plate.filter(c=>c.genomeId===genome.id),mutationTotal=genome.mutations||0;return `${pageHead(`MOLECULAR RECORD · ${genome.id}`,'Genome explorer','A living sequence, transcribed and translated into phenotype.',S.inspectedGenome?'<button class="subtle-button" data-view="cell">← Observatory</button><button class="action-button primary" data-action="clear-inspection">× Clear inspection</button>':`<button class="subtle-button" data-action="sequence">${S.samples.dna?'↻ Resequence':'⌁ Sequence genome'}</button><button class="action-button primary" data-action="save-genome">＋ Archive genome</button>`)}<div class="metric-strip">${metric('ASSEMBLED LENGTH',`${genome.sequence.length.toLocaleString()}<small> bp</small>`,'estimated · simulated reference')}${metric('GC CONTENT',`${f(gc(genome.sequence),1)}<small>%</small>`,'sequence composition')}${metric('PREDICTED GENES',genome.genes.length,'annotated ORFs')}${metric('CHROMOSOMES',genome.chromosomes,'haploid model')}</div>${S.inspectedGenome?`<section class="card" style="margin-bottom:14px"><div class="card-head"><span class="card-title">Lineage &amp; mutation record</span><span class="card-meta">PLATE SOURCE · ${lineageCells.length} CELL${lineageCells.length===1?'':'S'}</span></div><div class="gene-detail"><div class="chip-row"><span class="chip">GENERATION ${genome.generation||0}</span><span class="chip">${mutationTotal} MUTATION${mutationTotal===1?'':'S'}</span><span class="chip">${genome.origin?`PARENT ${genome.origin}`:'FOUNDING SOURCE'}</span></div><p>${genome.mutationDetails?.length?genome.mutationDetails.map(m=>`${m.name} ${m.from}→${m.to} at coding position ${m.position}`).join(' · '):'No coding mutations recorded for this genome.'}</p></div></section>`:''}<div class="section-grid"><section class="card"><div class="card-head"><span class="card-title">Gene annotation <span class="card-meta">/ ${genome.genes.length} loci</span></span><span class="tag green">LIVE EXPRESSION</span></div><div class="gene-list">${geneRows()}</div></section><div style="display:grid;gap:14px;align-content:start"><section class="card"><div class="card-head"><span class="card-title">Locus sequence · ${g.id}</span><span class="tag">CHROMOSOME ${g.chromosome}</span></div><div class="gene-detail"><div class="sequence-display"><div>${sequence}</div><div class="sequence-caption"><span>5′ → 3′ · CODING STRAND</span><span>${slice.length} BP</span></div></div><div class="chip-row"><span class="chip">PROMOTER ${g.promoter}</span><span class="chip">ENHANCER ${g.enhancer}</span><span class="chip">${g.intron.length} BP INTRON</span></div><p><strong style="color:#dce4dd">${g.name}</strong> — ${g.role}. ${g.regulation} regulation. Predicted peptide: <span style="color:var(--lime);font-family:var(--mono)">${translate(transcribe(g))}</span></p><div class="mini-stat"><span>EXPRESSION LEVEL · RELATIVE MODEL UNITS</span><strong class="stat-good">${f(traitMap(genome,S.env)[g.name],3)}<small>× baseline</small></strong></div></div></section><section class="card"><div class="card-head"><span class="card-title">Sequence context</span><span class="card-meta">NON-CODING DNA</span></div><div class="gene-detail"><div class="sequence-display">${S.genome.noncoding.slice(0,84).split('').map((x,i)=>`<span style="color:${['#9bafa3','#9bd8c3','#d0b77e','#a6c078'][i%4]}">${x}</span>`).join('')}<div class="sequence-caption"><span>INTERGENIC REGION</span><span>84 BP SHOWN</span></div></div><p>Non-coding sequence contributes regulatory context in this model; sequence shown is generated, not a reference biological genome.</p></div></section></div></div>`}
